#### windowShouldClose: (src/cocoa/fg_window_cocoa.m:116)

```objc
- (BOOL)windowShouldClose:(NSWindow *)sender
{
    AUTORELEASE_POOL;

    //
    // Keep ownership/lifetime under freeglut control. AppKit closes the
    // NSWindow immediately if we return YES, but freeglut destroys windows
    // later via the WindowsToDestroy queue handled in fgCloseWindows.
    //
    if ( !self.fgWindow ) {
        return YES;
    }

    if ( self.closeRequested ) { // idempotent guard
        fgWarning( "Window close already requested" );
    }
    else {
        self.closeRequested = YES;
        glutDestroyWindow( self.fgWindow->ID ); // Queue freeglut cleanup
        shouldQuit = YES;

        // Handle ActionOnWindowClose the same way X11 and Windows do
        if ( fgState.ActionOnWindowClose == GLUT_ACTION_EXIT ) {
            fgDeinitialize( );
            exit( 0 );
        }
        else if ( fgState.ActionOnWindowClose == GLUT_ACTION_GLUTMAINLOOP_RETURNS ) {
            fgState.ExecState = GLUT_EXEC_STATE_STOP;
        }
    }

    return NO;
}
```

#### windowDidChangeOcclusionState: (src/cocoa/fg_window_cocoa.m:150)

```objc
- (void)windowDidChangeOcclusionState:(NSNotification *)notification
{
    AUTORELEASE_POOL;

    BOOL isVisible               = [notification.object occlusionState] & NSWindowOcclusionStateVisible;
    self.fgWindow->State.Visible = isVisible;

    if ( isVisible ) {
        INVOKE_WCB( *self.fgWindow, WindowStatus, ( GLUT_FULLY_RETAINED ) );
    }
    else {
        INVOKE_WCB( *self.fgWindow, WindowStatus, ( GLUT_FULLY_COVERED ) );
    }
}
